#include <cmath>
#include <cstddef>
extern "C" long long tsvc_s351_direct_unrolled_saxpy(const double*x,std::size_t l,double*y,std::size_t cap){if(!x||l<12||l>82)return -1;double rd=x[0];if(!std::isfinite(rd)||std::trunc(rd)!=rd||rd<5||rd>40)return -1;auto n=(std::size_t)rd;if(n%5||l!=2+2*n)return -1;for(std::size_t i=1;i<l;i++)if(!std::isfinite(x[i])||std::trunc(x[i])!=x[i]||std::abs(x[i])>1)return -1;if(!y||cap<n)return -2;double a[40];for(std::size_t i=0;i<n;i++)a[i]=x[2+i];double alpha=x[1];for(std::size_t base=0;base<n;base+=5){double p0=alpha*x[2+n+base];a[base]=a[base]+p0;double p1=alpha*x[2+n+base+1];a[base+1]=a[base+1]+p1;double p2=alpha*x[2+n+base+2];a[base+2]=a[base+2]+p2;double p3=alpha*x[2+n+base+3];a[base+3]=a[base+3]+p3;double p4=alpha*x[2+n+base+4];a[base+4]=a[base+4]+p4;}for(std::size_t i=0;i<n;i++)y[i]=a[i];return (long long)n;}
